window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-inbox-macros.html"]="<!-- Settings: Macros -->\n<style>\n.mc-empty{text-align:center;padding:40px;color:var(--muted);font-size:13px}\n.mc-preview{max-width:300px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px;color:var(--muted)}\n.mc-del-confirm{background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:12px;margin:10px 0;font-size:13px;color:var(--danger)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">🏢 Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">👥 Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">🔐 Peran</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">🏷️ Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">🕐 Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">🔄 Auto-Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">📥 Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">⏱️ SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">⭐ CSAT</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/inbox-macros')\">⚡ Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">🎫 Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">🟢 WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">🔵 WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">💬 Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">🔗 Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:16px\">\n      <div>\n        <h2 style=\"margin:0 0 4px\">⚡ Makro Balasan Cepat</h2>\n        <p style=\"color:var(--muted);font-size:13px;margin:0\">Template balasan yang bisa dipilih agen saat membalas pesan.</p>\n      </div>\n      <button class=\"btn primary\" onclick=\"openMacroModal()\">+ Tambah Makro</button>\n    </div>\n\n    <table class=\"data-table\">\n      <thead><tr><th>Nama</th><th>Preview Balasan</th><th></th></tr></thead>\n      <tbody id=\"mcBody\"></tbody>\n    </table>\n  </div>\n</div>\n\n<!-- Add/Edit Modal -->\n<div class=\"modal-overlay\" id=\"mcModal\">\n  <div class=\"modal\" style=\"max-width:500px\">\n    <h3 id=\"mcTitle\">Tambah Makro</h3>\n    <label>Nama makro<input id=\"mcName\" placeholder=\"Greeting\"></label>\n    <label>Isi balasan<textarea id=\"mcReply\" rows=\"4\" placeholder=\"Halo kak, terima kasih telah menghubungi kami...\" style=\"width:100%;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg);resize:vertical;font-family:inherit\"></textarea></label>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeModal('mcModal')\">Batal</button>\n      <button class=\"btn primary\" onclick=\"saveMacro()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<!-- Delete Confirm Modal -->\n<div class=\"modal-overlay\" id=\"mcDelModal\">\n  <div class=\"modal\">\n    <h3>Hapus Makro</h3>\n    <div class=\"mc-del-confirm\" id=\"mcDelMsg\"></div>\n    <div class=\"modal-actions\">\n      <button class=\"btn\" onclick=\"closeModal('mcDelModal')\">Batal</button>\n      <button class=\"btn danger\" onclick=\"doDeleteMacro()\">Hapus</button>\n    </div>\n  </div>\n</div>\n\n<script>\nvar _editId = null;\nvar _delId = null;\n\nfunction renderMacros(){\n  const list = DB.settings.macros || [];\n  const tbody = document.getElementById('mcBody');\n  if(!list.length){\n    tbody.innerHTML = '<tr><td colspan=\"3\" class=\"mc-empty\">Belum ada makro. Tambahkan makro pertama Anda.</td></tr>';\n    return;\n  }\n  tbody.innerHTML = list.map(m => `\n    <tr>\n      <td><strong>${m.name}</strong></td>\n      <td><div class=\"mc-preview\">${m.reply}</div></td>\n      <td style=\"text-align:right;white-space:nowrap\">\n        <button class=\"btn\" onclick=\"openEditMacro('${m.id}')\">✏️</button>\n        <button class=\"btn danger\" onclick=\"openDelMacro('${m.id}')\">🗑️</button>\n      </td>\n    </tr>\n  `).join('');\n}\n\nfunction openMacroModal(){\n  _editId = null;\n  document.getElementById('mcTitle').textContent = 'Tambah Makro';\n  document.getElementById('mcName').value = '';\n  document.getElementById('mcReply').value = '';\n  document.getElementById('mcModal').classList.add('open');\n}\n\nfunction openEditMacro(id){\n  const m = DB.settings.macros.find(x=>x.id===id);\n  if(!m) return;\n  _editId = id;\n  document.getElementById('mcTitle').textContent = 'Edit Makro';\n  document.getElementById('mcName').value = m.name;\n  document.getElementById('mcReply').value = m.reply;\n  document.getElementById('mcModal').classList.add('open');\n}\n\nfunction saveMacro(){\n  const name = document.getElementById('mcName').value.trim();\n  const reply = document.getElementById('mcReply').value.trim();\n  if(!name || !reply){ showToast('Nama dan isi balasan wajib diisi'); return; }\n  if(_editId){\n    const i = DB.settings.macros.findIndex(x=>x.id===_editId);\n    if(i>=0) DB.settings.macros[i] = {...DB.settings.macros[i], name, reply};\n  } else {\n    DB.settings.macros.push({id:genId('mc'), name, reply});\n  }\n  saveStore();\n  closeModal('mcModal');\n  renderMacros();\n  showToast(_editId ? 'Makro diperbarui' : 'Makro ditambahkan');\n}\n\nfunction openDelMacro(id){\n  const m = DB.settings.macros.find(x=>x.id===id);\n  if(!m) return;\n  _delId = id;\n  document.getElementById('mcDelMsg').textContent = `Yakin ingin menghapus makro \"${m.name}\"?`;\n  document.getElementById('mcDelModal').classList.add('open');\n}\n\nfunction doDeleteMacro(){\n  DB.settings.macros = DB.settings.macros.filter(x=>x.id!==_delId);\n  saveStore();\n  closeModal('mcDelModal');\n  renderMacros();\n  showToast('Makro dihapus');\n}\n\nrenderMacros();\n</script>\n";
